from fnmatch import *


def divisors(num):
    div = []
    for j in range(1, int(num**0.5)+1):
        if num % j == 0:
            div.append(j)
            div.append(num // j)
    return sorted(set(div))


for x in range(53, 10**7, 53):  
    if fnmatch(str(x), '*2?2*'):  
        if str(x) == str(x)[::-1]:  
            d = divisors(x)
            if len(d) > 30:  
                print(x, sum(d))
